custom_css:
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;600;700;800&display=swap');

/* =========================================================
   0. PALETTE & GLOBAL RESET
   ========================================================= */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal, #moodtube-dock {
  --ps-bg: #0d1217;
  --ps-surface: #131920;
  --ps-surface-card: rgba(19, 25, 32, 0.92);
  --ps-green: #57c7ff;
  --ps-green-dim: #2b8fc4;
  --ps-yellow: #f1fa8c;
  --ps-cyan: #b4f9a0;
  --ps-blue: #7aa2f7;
  --ps-magenta: #ff6ac1;
  --ps-red: #ff5c57;
  --ps-text: #e6edf3;
  --ps-text-dim: #8fd5f5;
  --ps-text-muted: #6e7681;
  --ps-border: rgba(87, 199, 255, 0.35);
  --ps-border-subtle: rgba(87, 199, 255, 0.15);

  --mt-text: var(--ps-text);
  --mt-text-dim: var(--ps-text-dim);
  --mt-text-on-accent: #0d1217;
  --mt-overlay: rgba(5, 8, 12, 0.8);
  --mt-modal-shadow: 0 16px 36px rgba(0, 0, 0, 0.85);
  --mt-text-strong: #ffffff;
  --mt-divider: var(--ps-border-subtle);
  --mt-pl-spotify-tab: #18222d;
  --mt-pl-spotify-tab-text: var(--ps-cyan);
}

#moodtube-mini-player, #moodtube-mini-player *, #mt-settings-modal, #mt-settings-modal *, .mt-fab, .mt-fab *, .mt-pl-modal, .mt-pl-modal *, #moodtube-dock, #moodtube-dock * {
  text-shadow: none;
}

/* =========================================================
   1. TERMINAL WINDOW FRAME (.mt-player)
   ========================================================= */
.mt-player {
  container-type: size;
  background: #0d1217;
  border: 1px solid var(--ps-border);
  border-radius: 9px;
  box-shadow: 0 18px 45px rgba(0, 0, 0, 0.8), 0 0 1px 1px rgba(87, 199, 255, 0.25);
  backdrop-filter: blur(12px);
  color: var(--ps-text);
  font-family: 'JetBrains Mono', 'Consolas', monospace;
  padding: 44px 16px 18px 16px;
  box-sizing: border-box;
}

.mt-player * {
  font-family: inherit;
  box-sizing: border-box;
}

.mt-player i {
  font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome;
}

/* Background Terminal Tabs Bar */
.mt-slot.mt-slot-bg {
  z-index: 0;
  background: #080c10;
  border-bottom: 1px solid var(--ps-border);
  height: 34px;
  inset: 0 0 auto 0;
}

/* Terminal Window Tab */
.mt-slot-bg::before {
  content: '>_ pwsh';
  position: absolute;
  top: 5px;
  left: 12px;
  height: 29px;
  background: #0d1217;
  border: 1px solid var(--ps-border);
  border-bottom: none;
  border-radius: 6px 6px 0 0;
  padding: 5px 22px 0 10px;
  color: var(--ps-green);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

/* Terminal Tab Close 'x' */
.mt-slot-bg::after {
  content: '×';
  position: absolute;
  top: 10px;
  left: 74px;
  font-size: 12px;
  line-height: 1;
  color: var(--ps-text-muted);
}

/* Header Sub-bar */
.mt-player-header {
  top: 10px;
  left: 102px;
  right: 88px;
  z-index: 4;
  display: flex;
  align-items: center;
  gap: 8px;
}

.mt-player-header-title {
  font-size: 11px;
  color: var(--ps-text-muted);
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mt-player-status {
  font-size: 9px;
  padding: 1px 6px;
  border-radius: 3px;
  background: rgba(87, 199, 255, 0.15);
  border: 1px solid var(--ps-green-dim);
  color: var(--ps-green);
  font-weight: 700;
  letter-spacing: 1px;
}

/* Window Controls (Minimize, Maximize, Close) */
.mt-window-btn {
  top: 7px;
  width: 20px;
  height: 20px;
  font-size: 10px;
  color: var(--ps-text-muted);
  background: transparent;
  border: none;
  border-radius: 3px;
  transition: all 0.15s ease;
  display: flex;
  align-items: center;
  justify-content: center;
}

.mt-window-btn:hover {
  color: var(--ps-text);
  background: rgba(255, 255, 255, 0.08);
}

.mt-window-btn.mt-btn-close:hover {
  background: var(--ps-red);
  color: #fff;
}

.mt-window-btn.mt-btn-search { right: 60px; }
.mt-window-btn.mt-btn-settings { right: 38px; }
.mt-window-btn.mt-btn-close { right: 14px; }

/* =========================================================
   2. TERMINAL BODY & FASTFETCH REQUISITES
   ========================================================= */
.mt-player-body {
  gap: 12px;
  z-index: 2;
}

/* Prompt line at bottom (PS C:\Users\MoodTube> █) */
.mt-player-body::after {
  content: 'PS C:\\Users\\MoodTube> _';
  display: block;
  width: 100%;
  font-size: 10.5px;
  color: var(--ps-green);
  font-weight: 600;
  text-align: left;
  padding: 4px 6px;
  margin-top: 2px;
  border-top: 1px dashed var(--ps-border-subtle);
  letter-spacing: 0.5px;
  animation: ps-cursor-blink 1s steps(2, start) infinite;
}

@keyframes ps-cursor-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

/* =========================================================
   3. CRT / MATRIX SCREEN COVER (.mt-cover)
   ========================================================= */
.mt-cover {
  width: 120px;
  height: 120px;
  border-radius: 4px;
  border: 1px solid var(--ps-green);
  background: #05080c;
  overflow: hidden;
  box-shadow: 0 0 12px rgba(87, 199, 255, 0.25), inset 0 0 8px rgba(0, 0, 0, 0.8);
  position: relative;
}

.mt-cover img.mt-cover-img {
  border-radius: 0;
  filter: contrast(1.1) brightness(0.95);
}

/* Dot-matrix scanline overlay on cover */
.mt-slot-cover {
  z-index: 2;
  background: radial-gradient(rgba(87, 199, 255, 0.22) 15%, transparent 16%) 0 0 / 4px 4px,
              linear-gradient(rgba(0, 0, 0, 0.3) 50%, transparent 50%) 0 0 / 100% 2px;
  mix-blend-mode: color-dodge;
  pointer-events: none;
}

.mt-cover-hole {
  display: none;
}

/* =========================================================
   4. HARDWARE/METRICS BOX (.mt-track-info)
   ========================================================= */
.mt-track-info {
  position: relative;
  width: 100%;
  border: 1px solid var(--ps-border);
  border-radius: 4px;
  padding: 12px 10px 8px 10px;
  background: var(--ps-surface-card);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  text-align: left;
}

/* Fieldset Label (— Audio Session —) */
.mt-track-info::before {
  content: '— Hardware & Session —';
  position: absolute;
  top: -0.6em;
  left: 10px;
  background: #0d1217;
  padding: 0 6px;
  font-size: 9.5px;
  font-weight: 700;
  color: var(--ps-yellow);
  letter-spacing: 0.5px;
}

.mt-track-title {
  font-size: 12px;
  font-weight: 700;
  color: #ffffff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  width: calc(100% - 24px);
  display: flex;
  align-items: center;
}

.mt-track-title::before {
  content: 'TRACK';
  margin-right: 8px;
  color: var(--ps-green);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.5px;
  flex-shrink: 0;
}

.mt-track-subtitle {
  font-size: 11px;
  color: var(--ps-cyan);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  width: 100%;
  display: flex;
  align-items: center;
}

.mt-track-subtitle::before {
  content: 'ARTIST';
  margin-right: 8px;
  color: var(--ps-text-muted);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.5px;
  flex-shrink: 0;
}

.mt-btn-favorite {
  color: var(--ps-text-muted);
  right: 8px;
  top: 10px;
  font-size: 12px;
  background: transparent;
  border: none;
  box-shadow: none;
}

.mt-btn-favorite.mt-is-active {
  color: var(--ps-red);
}

/* =========================================================
   5. PROGRESS & VOLUME (BLOCK/CHARACTER STYLE METERS)
   ========================================================= */
.mt-progress {
  --mt-slider-track: repeating-linear-gradient(90deg, #1b2631 0px, #1b2631 6px, #0d1217 6px, #0d1217 8px);
  --mt-slider-track-height: 8px;
  --mt-slider-track-radius: 1px;
  --mt-slider-progress: repeating-linear-gradient(90deg, var(--ps-green) 0px, var(--ps-green) 6px, #0d1217 6px, #0d1217 8px);
  --mt-slider-thumb-size: 10px;
  --mt-slider-thumb-bg: var(--ps-yellow);
  --mt-slider-thumb-border: 1px solid #000;
  --mt-slider-thumb-radius: 1px;
  --mt-slider-thumb-shadow: none;
  width: 100%;
  position: relative;
}

.mt-time-current, .mt-time-total {
  font-size: 10px;
  color: var(--ps-text-muted);
  font-weight: 600;
}

.mt-volume {
  --mt-slider-track: repeating-linear-gradient(90deg, #1b2631 0px, #1b2631 5px, #0d1217 5px, #0d1217 7px);
  --mt-slider-track-height: 6px;
  --mt-slider-track-radius: 1px;
  --mt-slider-progress: repeating-linear-gradient(90deg, var(--ps-cyan) 0px, var(--ps-cyan) 5px, #0d1217 5px, #0d1217 7px);
  --mt-slider-thumb-size: 8px;
  --mt-slider-thumb-bg: var(--ps-cyan);
  --mt-slider-thumb-border: none;
  --mt-slider-thumb-radius: 1px;
  width: 100%;
}

.mt-volume-low, .mt-volume-high {
  font-size: 10px;
  color: var(--ps-text-muted);
}

/* =========================================================
   6. CONTROLS (TERMINAL BADGES)
   ========================================================= */
.mt-controls {
  gap: 8px;
  justify-content: center;
  align-items: center;
}

.mt-controls > .mt-btn {
  width: 32px;
  height: 30px;
  font-size: 11px;
  padding: 0;
  line-height: 1;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #141b22;
  border: 1px solid var(--ps-border);
  border-radius: 4px;
  color: var(--ps-green);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
  transition: all 0.1s ease;
}

.mt-controls > .mt-btn:hover {
  background: #1c2630;
  border-color: var(--ps-green);
  color: #ffffff;
  transform: translateY(-1px);
}

.mt-controls > .mt-btn:active {
  transform: translateY(1px);
}

.mt-controls > .mt-btn-play {
  width: 44px;
  height: 32px;
  font-size: 13px;
  background: var(--ps-green);
  border: 1px solid var(--ps-green);
  color: #0d1217;
  font-weight: 700;
}

.mt-controls > .mt-btn-play:hover {
  background: #8ad8ff;
  border-color: #8ad8ff;
  color: #0d1217;
}

.mt-btn-play.fa-play {
  padding-left: 2px;
}

.mt-controls > .mt-btn.mt-btn-ai.mt-is-busy {
  background: rgba(241, 250, 140, 0.15);
  border-color: var(--ps-yellow);
  color: var(--ps-yellow);
}

/* =========================================================
   7. QUEUE, PLAYLISTS & SEARCH PANELS
   ========================================================= */
.mt-panel {
  background: #0d1217;
  color: var(--ps-text);
  padding-top: 42px;
  border-radius: inherit;
  border: 1px solid var(--ps-border);
}

.mt-panel-header {
  border-bottom: 1px solid var(--ps-border-subtle);
  padding-bottom: 8px;
}

.mt-panel-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--ps-yellow);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.mt-panel-title::before {
  content: '> ';
  color: var(--ps-green);
}

.mt-panel-queue .mt-panel-list {
  counter-reset: queue-idx;
}

.mt-queue-item {
  border: 1px solid transparent;
  border-radius: 3px;
  margin-bottom: 3px;
  background: rgba(22, 27, 34, 0.6);
  padding: 5px 8px;
}

.mt-queue-item::before {
  counter-increment: queue-idx;
  content: '[' counter(queue-idx, decimal-leading-zero) '] ';
  font-size: 10px;
  color: var(--ps-text-muted);
  font-weight: 700;
  flex-shrink: 0;
  margin-right: 6px;
}

.mt-queue-item.mt-is-current {
  border-color: var(--ps-green);
  background: rgba(87, 199, 255, 0.1);
}

.mt-queue-item.mt-is-current::before {
  content: '>> ';
  color: var(--ps-green);
}

.mt-queue-title {
  font-size: 11px;
  color: var(--ps-text);
}

.mt-queue-dislike {
  background-color: var(--ps-text-muted);
}

.mt-queue-dislike:hover {
  background-color: var(--ps-red);
}

.mt-queue-now, .mt-queue-add {
  color: var(--ps-text-muted);
}

.mt-queue-now:hover, .mt-queue-add:hover {
  color: var(--ps-green);
}

/* Search Bar Form Lock Compliance */
.mt-panel-search {
  --mt-bg-primary: #0d1217;
}

#moodtube-search-input {
  background: #090d12;
  border: 1px solid var(--ps-border);
  color: var(--ps-text);
  font-family: inherit;
}

#moodtube-search-go {
  background: var(--ps-green);
  color: #0d1217;
  border: 1px solid var(--ps-green);
}

/* =========================================================
   8. MODALS & SETTINGS
   ========================================================= */
.mt-pl-modal-box {
  background: #0d1217;
  border: 1px solid var(--ps-green);
  border-radius: 8px;
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.9);
  color: var(--ps-text);
}

#mt-settings-modal .mt-flex-container {
  background: #0d1217;
  border: 1px solid var(--ps-border);
  border-radius: 8px;
  color: var(--ps-text);
}

#mt-settings-modal .mt-header h3 {
  color: var(--ps-green);
  font-family: 'JetBrains Mono', monospace;
}

#mt-settings-modal .mt-btn-test {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: #161b22;
  border: 1px solid var(--ps-border);
  color: var(--ps-green);
  border-radius: 4px;
  font-family: inherit;
  font-weight: 600;
}

#mt-settings-modal .mt-btn-test:hover {
  background: var(--ps-green);
  color: #0d1217;
}

.mt-tag, .mt-genre-tag, .mt-mood-tag, .mt-scenario-tag {
  background: #141b22;
  border: 1px solid var(--ps-border-subtle);
  color: var(--ps-text-dim);
}

.mt-tag.active, .mt-genre-tag.active, .mt-mood-tag.active, .mt-scenario-tag.active {
  background: var(--ps-green);
  border-color: var(--ps-green);
  color: #0d1217;
  font-weight: 700;
}

/* Floating Action Button (FAB): round, flat, no glow. When MoodTube docks it into the DreamAlbum
   floating window, that wrapper gets the theme colours instead of its default purple-black */
.mt-fab, .mt-fab.mt-fab-docked {
  background: #0d1217;
  color: var(--ps-green);
  border: 1.5px solid var(--ps-green);
  border-radius: 50%;
  box-shadow: none;
}

.mt-fab:hover, .mt-fab.mt-fab-docked:hover {
  background: var(--ps-green);
  color: #0d1217;
}

.DA-floating-window:has(.mt-fab) {
  background: #0d1217;
  border: 1px solid var(--ps-border);
  backdrop-filter: none;
}

/* =========================================================
   9. DOCKED BAR (UNDER SILLYTAVERN HEADER)
   ========================================================= */
#moodtube-dock {
  font-family: 'JetBrains Mono', monospace;
  --mt-dock-cover-radius: 3px;
  background: #0d1217;
  border-bottom: 1px solid var(--ps-border);
}

#moodtube-mini-player.mt-player-docked {
  background: #0d1217;
  border: none;
  box-shadow: none;
}

.mt-dock-title {
  color: #ffffff;
  font-size: 11.5px;
  font-weight: 700;
}

.mt-dock-subtitle {
  color: var(--ps-green);
  font-size: 10.5px;
}

.mt-dock-btn {
  width: 28px;
  height: 28px;
  font-size: 11px;
  background: #131920;
  border: 1px solid var(--ps-border);
  border-radius: 3px;
  color: var(--ps-green);
  display: flex;
  align-items: center;
  justify-content: center;
}

.mt-dock-btn.mt-dock-play {
  width: 34px;
  height: 30px;
  font-size: 13px;
  background: var(--ps-green);
  color: #0d1217;
}

.mt-dock-progress {
  height: 3px;
  background: repeating-linear-gradient(90deg, var(--ps-green) 0px, var(--ps-green) 6px, #0d1217 6px, #0d1217 8px);
}

/* =========================================================
   10. MODES & CONTAINER QUERIES
   ========================================================= */
/* Wide Row Layout (>= 560x260 / 640x175) */
.mt-player.moodtube-row-layout {
  padding: 40px 14px 12px 14px;
}

.mt-player.moodtube-row-layout .mt-cover {
  width: 60px;
  height: 60px;
  flex-shrink: 0;
}

.mt-player.moodtube-row-layout .mt-track-info {
  padding: 8px 8px 6px 8px;
  min-width: 130px;
}

.mt-player.moodtube-row-layout .mt-controls {
  gap: 6px;
}

.mt-player.moodtube-row-layout .mt-controls > .mt-btn {
  width: 28px;
  height: 26px;
  font-size: 10px;
}

.mt-player.moodtube-row-layout .mt-controls > .mt-btn-play {
  width: 36px;
  height: 28px;
  font-size: 12px;
}

@container (max-width: 640px) {
  .mt-player.moodtube-row-layout .mt-volume {
    display: none;
  }
}

@container (max-width: 300px) {
  .mt-player .mt-player-status {
    display: none;
  }
}

/* Compact View for genuinely small boxes (<190px width or <240px height) */
@container (max-width: 190px) {
  .mt-player {
    padding: 38px 8px 16px 8px;
  }
  .mt-controls {
    gap: 4px;
  }
  .mt-controls > .mt-btn {
    width: 24px;
    height: 24px;
    font-size: 9.5px;
  }
  .mt-controls > .mt-btn-play {
    width: 28px;
    height: 26px;
    font-size: 11px;
  }
  .mt-player-body::after {
    display: none;
  }
}

@container (max-height: 240px) {
  .mt-player-body::after {
    display: none;
  }
  .mt-cover {
    width: 70px;
    height: 70px;
  }
}
/* queue: numbers instead of thumbnails, so titles get the room; panel title no longer cut by the window buttons */
.mt-queue-thumb { display: none; }
.mt-panel-header-left { margin-right: 20px; }

/* ===== Dock bar (strip under the tavern header) [auto] ===== */
#moodtube-dock {
  font-family: 'JetBrains Mono', 'Consolas', monospace;
  --mt-dock-cover-radius: 3px;
}
#moodtube-dock, #moodtube-dock * { text-shadow: none; }
#moodtube-dock .mt-dock-cover { border-width: 1.5px; }
#moodtube-dock .mt-dock-controls { gap: 6px; }
#moodtube-dock .mt-dock-btn {
  width: 28px; height: 28px; padding: 0; box-sizing: border-box; line-height: 1; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; border-radius: 3px;
  font-size: 12px; color: var(--mt-text);
  background: color-mix(in srgb, var(--mt-accent) 12%, transparent);
  transform: none; transition: background-color 0.2s;
}
#moodtube-dock .mt-dock-btn:hover { transform: none; color: var(--mt-text); background: color-mix(in srgb, var(--mt-accent) 28%, transparent); }
#moodtube-dock .mt-dock-play {
  width: 34px; height: 34px; font-size: 14px;
  background: var(--mt-accent); color: var(--mt-text-on-accent, #ffffff);
}
#moodtube-dock .mt-dock-play:hover { background: var(--mt-accent-hover, var(--mt-accent)); color: var(--mt-text-on-accent, #ffffff); }
#moodtube-dock .mt-dock-play.fa-play { padding-left: 2px; }
#moodtube-dock .mt-dock-fav, #moodtube-dock .mt-dock-ai, #moodtube-dock .mt-dock-queue { color: var(--mt-text); }
#moodtube-dock .mt-dock-fav.mt-is-active, #moodtube-dock .mt-dock-ai.mt-is-busy { color: var(--mt-accent); }
#moodtube-dock .mt-dock-expand, #moodtube-dock .mt-dock-close { color: var(--mt-text-dim, var(--mt-text)); }
#moodtube-dock .mt-dock-queue.mt-is-open, #moodtube-dock .mt-dock-expand.mt-is-open {
  color: var(--mt-text); text-shadow: none; background: color-mix(in srgb, var(--mt-accent) 30%, transparent);
}
#moodtube-dock .mt-dock-progress { height: 3px; }
@media (max-width: 420px) {
  #moodtube-dock .mt-dock-inner { gap: 6px; padding-left: 8px; padding-right: 8px; }
  #moodtube-dock .mt-dock-controls { gap: 3px; }
  #moodtube-dock .mt-dock-btn { width: 24px; height: 24px; font-size: 11px; }
  #moodtube-dock .mt-dock-play { width: 28px; height: 28px; font-size: 12px; }
}
/* ===== /Dock bar ===== */
/* == lyrics button == the fourth window button, in line with search / settings / close */
.mt-player .mt-window-btn.mt-btn-lyrics { right: 82px; }
.mt-player .mt-lyrics-body { scrollbar-width: none; }
.mt-player .mt-lyrics-body::-webkit-scrollbar { display: none; width: 0; }
.mt-player-header { right: 110px; }
